// Generated by Cypress Author on 2026-11-10.
// The chat window: history, message requests and file sharing over REST.
// Live delivery needs the Socket.IO server, which these stubbed specs leave out.
import { buildConversation, buildMessage } from "../support/data";

describe("Messages", () => {
  beforeEach(() => {
    cy.stubApi();
    cy.intercept("PATCH", "/api/conversations/*/read", { body: { message: "Marked as read" } }).as("markRead");
  });

  /** Stubs the inbox, one open conversation and its history, then opens it */
  function openConversation(conversation = buildConversation(), messages = [buildMessage()]) {
    cy.intercept("GET", "/api/conversations?tab=*", { body: [conversation] }).as("list");
    cy.intercept("GET", `/api/conversations/${conversation.id}`, { body: conversation }).as("conversation");
    cy.intercept("GET", `/api/conversations/${conversation.id}/messages*`, {
      body: { messages, hasMore: false, nextCursor: null },
    }).as("history");
    cy.visitSignedIn(`/messages/${conversation.id}`);
    cy.wait(["@conversation", "@history"]);
  }

  it("opening a conversation → shows its history and marks it read", () => {
    openConversation(buildConversation(), [
      buildMessage({ id: "m1", text: "Is the textbook still available?" }),
      buildMessage({ id: "m2", senderId: "student-1", text: "Yes, it is!", createdAt: "2026-11-01T12:02:00.000Z" }),
    ]);

    cy.contains("Is the textbook still available?").should("be.visible");
    cy.contains("Yes, it is!").should("be.visible");
    cy.contains("Start of the conversation").should("be.visible");
    cy.wait("@markRead");
  });

  it("accepting a message request → sends the accept and shows the normal chat", () => {
    const request = buildConversation({ status: "PENDING", isRequest: true });
    openConversation(request);
    cy.contains("Sam Seller wants to message you").should("be.visible");

    // After accepting, the page reloads the conversation from the API
    cy.intercept("PATCH", "/api/conversations/conv-1/accept", { body: { message: "Request accepted" } }).as("accept");
    cy.intercept("GET", "/api/conversations/conv-1", { body: { ...request, status: "ACCEPTED", isRequest: false } }).as("accepted");
    cy.contains("button", "Accept").click();

    cy.wait("@accept");
    cy.wait("@accepted");
    cy.contains("wants to message you").should("not.exist");
    cy.get('textarea[placeholder="Write a message…"]').should("be.visible");
  });

  it("sharing a PDF → uploads it and shows it in the chat", () => {
    openConversation(buildConversation(), []);
    cy.contains("No messages yet. Say hello!").should("be.visible");

    cy.intercept("POST", "/api/conversations/conv-1/files", (req) => {
      req.reply({
        statusCode: 201,
        body: buildMessage({
          id: "file-msg",
          senderId: "student-1",
          text: "Shared notes.pdf",
          clientId: req.body.clientId,
          attachments: [{ url: "/api/files/f1/download", name: "notes.pdf", mimeType: "application/pdf", size: 8 }],
        }),
      });
    }).as("upload");

    cy.get('[aria-label="Choose a file to share"]').selectFile(
      { contents: Cypress.Buffer.from("%PDF-1.7"), fileName: "notes.pdf", mimeType: "application/pdf" },
      { force: true }, // the real input is visually hidden behind the Attach button
    );

    cy.wait("@upload").its("request.body").should("deep.include", { name: "notes.pdf", data: btoa("%PDF-1.7") });
    cy.contains("button", "notes.pdf").should("be.visible");
  });

  it("sending while the live connection is down → marks the message not sent with a retry", () => {
    openConversation(buildConversation(), []);

    cy.get('textarea[placeholder="Write a message…"]').type("Can we meet at 3?{enter}");

    cy.contains("Can we meet at 3?").should("be.visible");
    cy.contains("Not sent · You're offline").should("be.visible");
    cy.contains("button", "Retry").should("be.visible");
  });
});
